import Foundation
import CryptoKit

class SecureFileServer {
    private let baseDirectory: String
    private let hmacKey: SymmetricKey
    private let allowedExtensions = Set(["txt", "pdf", "png", "jpg", "html"])

    init(baseDirectory: String, secret: String) {
        self.baseDirectory = (baseDirectory as NSString).standardizingPath
        self.hmacKey = SymmetricKey(data: SHA256.hash(data: Data(secret.utf8)))
    }

    struct AccessToken {
        let username: String
        let expiry: Date
        let signature: Data
    }

    func validateToken(_ tokenString: String) -> AccessToken? {
        let parts = tokenString.split(separator: ".", maxSplits: 2)
        guard parts.count == 3 else { return nil }

        guard let userBytes = Data(base64Encoded: String(parts[0])),
              let expiryBytes = Data(base64Encoded: String(parts[1])),
              let signature = Data(base64Encoded: String(parts[2])) else { return nil }

        let username = String(data: userBytes, encoding: .utf8) ?? ""
        let expiryStr = String(data: expiryBytes, encoding: .utf8) ?? ""
        guard let expiryInterval = Double(expiryStr) else { return nil }
        let expiry = Date(timeIntervalSince1970: expiryInterval)

        // Verify HMAC
        let message = Data("\(parts[0]).\(parts[1])".utf8)
        let expectedMAC = HMAC<SHA256>.authenticationCode(for: message, using: hmacKey)
        guard signature == Data(expectedMAC) else { return nil }

        // Check expiry
        guard expiry > Date() else { return nil }

        return AccessToken(username: username, expiry: expiry, signature: signature)
    }

    /// Sanitizes a user-provided filename to prevent path traversal
    private func sanitizePath(_ input: String) -> String? {
        // Step 1: Normalize Unicode FIRST (NFD - decomposed form)
        // NFD only decomposes characters into base + combining marks
        // It CANNOT produce new ASCII characters like '/' or '.'
        let normalized = input.decomposedStringWithCanonicalMapping

        // Step 2: Reject any path traversal attempts on normalized string
        if normalized.contains("..") {
            return nil
        }

        // Step 3: Reject absolute paths
        if normalized.hasPrefix("/") || normalized.hasPrefix("\\") {
            return nil
        }

        // Step 4: Reject backslashes and null bytes
        if normalized.contains("\\") || normalized.contains("\0") {
            return nil
        }

        // Step 5: Reject any path separator in the filename
        if normalized.contains("/") {
            return nil
        }

        // Step 6: Validate extension
        let ext = (normalized as NSString).pathExtension.lowercased()
        guard allowedExtensions.contains(ext) else { return nil }

        // Step 7: Ensure it's a simple filename (no directory components)
        let components = normalized.split(separator: "/")
        guard components.count == 1 else { return nil }

        return normalized
    }

    func serveFile(token: String, requestedPath: String) -> (Int, Data?) {
        // Authenticate
        guard let _ = validateToken(token) else {
            return (401, nil)
        }

        // Sanitize the path - only allows simple filenames, no directories
        guard let safePath = sanitizePath(requestedPath) else {
            return (403, nil)
        }

        // Construct full path
        let fullPath = (baseDirectory as NSString).appendingPathComponent(safePath)

        // Final safety check: resolved path must be under base directory
        let resolvedPath = (fullPath as NSString).standardizingPath
        guard resolvedPath.hasPrefix(baseDirectory + "/") || resolvedPath == baseDirectory else {
            return (403, nil)
        }

        // Read and return file
        guard let data = FileManager.default.contents(atPath: resolvedPath) else {
            return (404, nil)
        }

        return (200, data)
    }

    /// Handles batch file listing with user-controlled depth parameter
    func listFiles(token: String, subdirectory: String, maxDepth: Int) -> (Int, [String]?) {
        guard let _ = validateToken(token) else {
            return (401, nil)
        }

        // Only allow listing the base directory itself
        guard subdirectory.isEmpty else {
            return (403, nil)
        }

        let targetDir = baseDirectory

        // Clamp depth to 1 - only list immediate files
        let depth = 1

        var results: [String] = []
        collectFiles(at: targetDir, currentDepth: 0, maxDepth: depth, results: &results)

        return (200, results)
    }

    private func collectFiles(at path: String, currentDepth: Int, maxDepth: Int, results: inout [String]) {
        guard currentDepth < maxDepth else { return }

        let fm = FileManager.default
        guard let items = try? fm.contentsOfDirectory(atPath: path) else { return }

        for item in items {
            let fullItem = (path as NSString).appendingPathComponent(item)
            var isDir: ObjCBool = false
            if fm.fileExists(atPath: fullItem, isDirectory: &isDir) {
                if !isDir.boolValue {
                    // Only list files with allowed extensions
                    let ext = (item as NSString).pathExtension.lowercased()
                    if allowedExtensions.contains(ext) {
                        // Return relative path only, not full system path
                        results.append(item)
                    }
                }
            }
        }
    }
}

// MARK: - Request Router
class RequestRouter {
    let server: SecureFileServer

    init(server: SecureFileServer) {
        self.server = server
    }

    enum RouteResult {
        case fileResponse(Int, Data?)
        case listResponse(Int, [String]?)
        case error(Int, String)
    }

    func handleRequest(method: String, path: String, headers: [String: String], body: Data?) -> RouteResult {
        guard let authHeader = headers["Authorization"],
              authHeader.hasPrefix("Bearer ") else {
            return .error(401, "Missing authorization")
        }

        let token = String(authHeader.dropFirst(7))

        switch (method.uppercased(), path) {
        case ("GET", let p) where p.hasPrefix("/files/"):
            let filePath = String(p.dropFirst(7))
            let (status, data) = server.serveFile(token: token, requestedPath: filePath)
            return .fileResponse(status, data)

        case ("GET", let p) where p.hasPrefix("/list"):
            let (status, files) = server.listFiles(token: token, subdirectory: "", maxDepth: 1)
            return .listResponse(status, files)

        default:
            return .error(404, "Not found")
        }
    }
}
